import polars as pl

frame = pl.DataFrame(
    {
        "id": [3, 1, 2, 4],
        "customer": ["A", "A", "B", "A"],
        "time": [2, 1, 1, 3],
        "value": [5, 2, 7, 4],
    }
)
output = frame.sort("customer", "time", "id").with_columns(
    pl.col("value").cum_sum().shift(1).over("customer").alias("running_before")
)
assert output.filter(pl.col("customer") == "A")["running_before"].to_list() == [None, 2, 7]

import polars as pl

status = pl.Enum(["new", "paid", "shipped"])
try:
    pl.Series(["new", "cancelled"]).cast(status)
except pl.exceptions.InvalidOperationError:
    rejected = True
else:
    rejected = False
assert rejected
